export type TemperatureUnit = "C" | "F";

export interface Reading {
  minute: number;
  temperature: number;
  humidity: number;
  code: string;
}

export interface ConvertedReading extends Reading {
  unit: TemperatureUnit;
}

export class ClimateArchive {
  private readonly readings: Reading[];

  constructor(input: readonly Reading[]) {
    const seen = new Set<number>();
    this.readings = input.map((reading) => {
      if (!Number.isInteger(reading.minute) || seen.has(reading.minute)) {
        throw new Error("Minutes must be unique integers");
      }
      if (!Number.isFinite(reading.temperature)) {
        throw new Error("Temperature must be finite");
      }
      if (!Number.isFinite(reading.humidity) || reading.humidity < 0 || reading.humidity > 100) {
        throw new Error("Humidity must be between 0 and 100");
      }
      if (reading.code.trim() === "") throw new Error("Code must be non-blank");
      seen.add(reading.minute);
      return { ...reading };
    }).sort((a, b) => a.minute - b.minute);
  }

  latest(unit: TemperatureUnit = "C"): ConvertedReading | undefined {
    const reading = this.readings[this.readings.length - 1];
    return reading === undefined ? undefined : this.convert(reading, unit);
  }

  window(startMinute: number, count: number, unit: TemperatureUnit = "C"): readonly ConvertedReading[] {
    if (!Number.isInteger(startMinute)) throw new Error("Start minute must be an integer");
    if (!Number.isInteger(count) || count < 0) throw new Error("Count must be a non-negative integer");
    return this.readings
      .filter((reading) => reading.minute >= startMinute)
      .slice(0, count)
      .map((reading) => this.convert(reading, unit));
  }

  private convert(reading: Reading, unit: TemperatureUnit): ConvertedReading {
    const temperature = unit === "F" ? reading.temperature * 9 / 5 : reading.temperature;
    return { ...reading, temperature, unit };
  }
}

