import { ClimateArchive } from './solution';
import type { ConvertedReading, Reading, TemperatureUnit } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => unknown, message: string): void {
  let failed = false;
  try { action(); } catch (error) { failed = error instanceof Error; }
  if (!failed) throw new Error(message);
}

const empty = new ClimateArchive([]);
equal(empty.latest(), undefined, 'empty latest');
equal(empty.window(0, 5).length, 0, 'empty window');

const invalidReadings: Reading[] = [
  { minute: 1.5, temperature: 20, humidity: 50, code: 'x' },
  { minute: 1, temperature: Number.NaN, humidity: 50, code: 'x' },
  { minute: 1, temperature: Number.POSITIVE_INFINITY, humidity: 50, code: 'x' },
  { minute: 1, temperature: 20, humidity: -1, code: 'x' },
  { minute: 1, temperature: 20, humidity: 101, code: 'x' },
  { minute: 1, temperature: 20, humidity: 50, code: '   ' }
];
for (const reading of invalidReadings) throws(() => new ClimateArchive([reading]), 'invalid reading must throw');
throws(() => new ClimateArchive([
  { minute: 2, temperature: 1, humidity: 1, code: 'a' },
  { minute: 2, temperature: 2, humidity: 2, code: 'b' }
]), 'duplicate minute must throw');

const mutable: Reading[] = [
  { minute: 20, temperature: 10, humidity: 40, code: 'late' },
  { minute: -2, temperature: -40, humidity: 0, code: 'early' },
  { minute: 5, temperature: 0, humidity: 100, code: 'middle' }
];
const archive = new ClimateArchive(mutable);
mutable[0].temperature = 999;
mutable.splice(0, mutable.length);

const all = archive.window(-2, 10);
equal(all.length, 3, 'window count');
equal(all[0].minute, -2, 'sorted first');
equal(all[1].minute, 5, 'sorted second');
equal(all[2].minute, 20, 'sorted third');
equal(all[2].temperature, 10, 'constructor copy');
equal(all[2].unit, 'C', 'default unit');

const fahrenheit: TemperatureUnit = 'F';
const converted = archive.window(0, 2, fahrenheit);
equal(converted.length, 2, 'count limits window');
equal(converted[0].minute, 5, 'start minute filter');
equal(converted[0].temperature, 32, 'freezing conversion');
equal(converted[1].temperature, 50, 'fahrenheit conversion');
equal(converted[0].unit, 'F', 'reported unit');

const latest = archive.latest('F');
if (latest === undefined) throw new Error('latest should exist');
equal(latest.minute, 20, 'latest minute');
equal(latest.temperature, 50, 'latest conversion');
(latest as { temperature: number }).temperature = -999;
(converted as ConvertedReading[]).reverse();
(converted[1] as { code: string }).code = 'changed';
equal(archive.latest('F')?.temperature, 50, 'latest is defensive');
equal(archive.window(0, 2, 'F')[0].code, 'middle', 'window is defensive');

equal(archive.window(0, 0).length, 0, 'zero count');
throws(() => archive.window(0.5, 1), 'noninteger start');
throws(() => archive.window(0, -1), 'negative count');
throws(() => archive.window(0, 1.5), 'noninteger count');

